def parseMoClassName(className: Any) -> object {
    idx = -1;
    upperFound = False;
    for c in className {
        idx += 1;
        if c.isupper() {
            upperFound = True;
            break;
        }
    }
    if upperFound {
        pkg = className[:idx];
        klass = className[idx:];
    } else {
        pkg = className;
        klass = "";
    }
